import { chromium } from 'playwright'; import fs from 'fs';
const BASE='https://www.statesideqm.com', THEME='158900125851', OUT='sep18-fast-baseline'; fs.mkdirSync(OUT,{recursive:true});
const purl=(r)=>{const u=new URL(r,BASE);u.searchParams.set('preview_theme_id',THEME);return u.href};
const clean=(h)=>{try{const u=new URL(h,BASE);if(u.origin!==new URL(BASE).origin)return null;u.searchParams.delete('preview_theme_id');return u.pathname+u.search}catch{return null}};
const visible=async p=>p.evaluate(()=>{const main=document.getElementById('MainContent')||document.body,ok=e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>8&&r.height>20};const out=[];for(const a of main.querySelectorAll('a[href]')){if(!ok(a))continue;let u;try{u=new URL(a.href,location.origin)}catch{continue}if(u.origin!==location.origin||!/^\/(collections|pages)\//.test(u.pathname)||/\/products\//.test(u.pathname))continue;u.searchParams.delete('preview_theme_id');const label=(a.getAttribute('aria-label')||a.textContent||a.querySelector('img')?.alt||'').replace(/\s+/g,' ').trim();if(!label)continue;const r=a.getBoundingClientRect(),card=!!(a.querySelector('img,svg')||a.closest('[class*="card"],[class*="grid"],[data-sq-state-guard-root]')||r.width>140||r.height>50);if(!card)continue;out.push({label:label.slice(0,180),route:u.pathname+u.search})}const seen=new Set;return out.filter(x=>!seen.has(x.route)&&(seen.add(x.route),true))});
const browser=await chromium.launch({headless:true}); const discoverCtx=await browser.newContext({viewport:{width:1440,height:1000}}); const d=await discoverCtx.newPage();
await d.goto(purl('/'),{waitUntil:'domcontentloaded',timeout:60000});await d.waitForTimeout(1000);const home=await visible(d);
await d.goto(purl('/collections/state-guard-series'),{waitUntil:'domcontentloaded',timeout:60000});await d.waitForTimeout(1000);const sg=await visible(d);
await discoverCtx.close();
const map=new Map;home.forEach(x=>map.set(x.route,{...x,group:'homepage'}));sg.forEach(x=>{if(!map.has(x.route))map.set(x.route,{...x,group:'state-guard-root'})});
const routes=[...map.values()], results=[], queue=[...routes];
async function worker(id){const ctx=await browser.newContext({viewport:{width:1440,height:1000}});const p=await ctx.newPage();await ctx.newCDPSession(p).then(c=>c.send('Network.setCacheDisabled',{cacheDisabled:true}));while(queue.length){const item=queue.shift();let resp=null,err=null;try{resp=await p.goto(purl(item.route),{waitUntil:'domcontentloaded',timeout:60000});await p.waitForLoadState('load',{timeout:12000}).catch(()=>{});await p.waitForTimeout(650)}catch(e){err=String(e?.message||e)}const m=await p.evaluate(()=>{const n=performance.getEntriesByType('navigation')[0],rs=performance.getEntriesByType('resource'),f=performance.getEntriesByName('first-contentful-paint')[0];return{ttfb:Math.round(n?.responseStart||0),dcl:Math.round(n?.domContentLoadedEventEnd||0),load:Math.round(n?.loadEventEnd||0),fcp:Math.round(f?.startTime||0),resources:rs.length,transfer:rs.reduce((s,r)=>s+(r.transferSize||0),0),dom:document.getElementsByTagName('*').length,scripts:document.scripts.length,images:document.images.length,title:document.title}}).catch(()=>({}));results.push({...item,status:resp?.status()??null,error:err,...m});console.log('FAST',id,item.group,item.label,m.ttfb,m.load,Math.round((m.transfer||0)/1024))}await ctx.close()}
await Promise.all([worker(1),worker(2)]);await browser.close();
results.sort((a,b)=>(b.load||0)-(a.load||0));const report={generatedAt:new Date().toISOString(),theme:THEME,homeCount:home.length,stateGuardRootCount:sg.length,total:results.length,results};fs.writeFileSync(OUT+'/results.json',JSON.stringify(report,null,2));fs.writeFileSync(OUT+'/coverage.json',JSON.stringify({home,sg},null,2));console.log('SUMMARY',JSON.stringify({homeCount:home.length,stateGuardRootCount:sg.length,total:results.length,avgHome:Math.round(results.filter(x=>x.group==='homepage').reduce((s,x)=>s+(x.load||0),0)/Math.max(1,results.filter(x=>x.group==='homepage').length)),avgSG:Math.round(results.filter(x=>x.group==='state-guard-root').reduce((s,x)=>s+(x.load||0),0)/Math.max(1,results.filter(x=>x.group==='state-guard-root').length)),slowest:results.slice(0,12).map(x=>({label:x.label,route:x.route,load:x.load,ttfb:x.ttfb,kb:Math.round((x.transfer||0)/1024),resources:x.resources}))}));